// ── Captures ────────────────────────────────────────────────────────────────
// Real captures of the viewer (scripts/seo/core-landings/capture.cjs), with the
// interface in English. The .jpg is the indexed file and carries the IPTC
// rights; the .webp renditions are what browsers download.

export const IMAGE_DIR = 'images/landings/'

export type ShotId = 'score3d' | 'issues' | 'clash' | 'ids' | 'export' | 'profile' | 'macProperties' | 'macSection'

export interface ShotImage {
  /** Name of the capture written by capture.cjs. */
  capture: string
  /** Published file name without extension, under IMAGE_DIR. */
  file: string
  width: number
  height: number
  /** Widths of the .webp renditions, `${file}-${w}.webp`. */
  webp: [number, number]
}

